-- ============================================================================
-- SC3: Materials, Spares & Inventory Management joins the catalogue in the
-- Supply Chain module. AN APP COURSE: the Suite app is the Materials & Spares
-- Planner (Midstream & Downstream); the practicals also run in the course's own
-- calculator panels over the same vendored engine.
--
-- Catalogue row (module 'supply_chain'; path_order 77; prereq_slug NULL,
-- the lead's decision; school left at its default) plus the three capstones and
-- their eighteen graded fields, generated by tools/course-waves/materials/gen_course.py
-- from the ENGINE'S OWN RUN (materials_capstone.mjs through the vendored
-- engines/supplychain/inventory.js, petrolord-engines 110f0a0), which it refuses
-- to write unless fields.json carries exactly that run's values and the
-- tolerance gradedTolerance.js derives. Deep seeds are three separate
-- migrations; the go-live is a fifth and is HELD until a NextGen production
-- upload carries the route /dashboard/apps/materials.
--
-- WHAT IS GRADED. IGBARIAM (Associate) grades a weighted criticality score, a
-- cumulative ABC share, an EOQ, its relevant cost at the rounded quantity and
-- the rounding penalty, and a total write-down; OGIDI (Professional) grades an
-- incremental-discount order quantity and its total cost, a safety stock at a
-- cycle service level, a fill-rate safety factor, an order-up-to level under
-- periodic review and a Poisson slow mover's expected units short; UMUCHU
-- (Expert) grades an insurance spare's total and downtime cost, probability of
-- no shortage and fill rate, and a seal's Poisson units short and fill rate;
-- its lead-time Monte Carlo block is worked and never graded. Every value is a
-- return value of the engine, identical under every reading the engine states
-- and never a Monte Carlo draw, and the data it was run on is in the case file
-- the prompt names.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('materials', 'Materials, Spares & Inventory Management', 'supply_chain', 77, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'materials', 'beginner', 'associate',
  'IGBARIAM, the materials register of the Igbariam flow station (synthetic)',
  'Criticality, classes and the order quantity',
  'IGBARIAM, the materials register of the Igbariam flow station (synthetic). One case file comes with this capstone: igbariam_case.json carries four calls under the keys criticality, abcClassification, eoq and slowMoving; paste it into the register calculator and choose the block each value needs. The item lists are in the case file. Criticality: safety weight 35; production weight 30; leadTime weight 20; redundancy weight 15; scores out of 4; classes V from 72, E from 45, D from 0; a maximum score on safety places an item in the top class. ABC by annual usage value: cut-offs of 75 and 92 percent under the at-or-below rule. The corrosion inhibitor: a demand of 130 drums a year, an order cost of 1450, a unit cost of 212, a holding rate of 0.24, rounding up to a multiple of 6. Slow-moving bands: active from 0 months at 0 percent; slow from 9 months at 20 percent; very slow from 18 months at 45 percent; obsolete from 30 months at 100 percent; excess above 18 months of cover. No value depends on any of the readings the engine states (twelve significant digits, halves upward, a minimum met at or above it, a tie to the smaller quantity or fewer spares, a Poisson target met at or above it, the cover limit exceeded strictly above it, a stockout at equality, the P90 as the low figure) or on a Monte Carlo draw, and every input a value needs is stated here or in the case file: the engine holds no default for any of them. Report six values: the weighted criticality score of the separator level control valve trim, IGB-V204; the cumulative share of annual usage value with the corrosion inhibitor, IGB-C515, included, in percent; the EOQ of the corrosion inhibitor, unrounded; its relevant cost a year at the quantity ordered; the rounding penalty, in percent; and the total write-down of the four banded items. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','igbariam_trim_weighted_score', 'label','The weighted criticality score of the separator level control valve trim, IGB-V204', 'unit','score out of 100', 'expected',66.25, 'tol',5e-07),
    jsonb_build_object('key','igbariam_inhibitor_cumulative_pct', 'label','The cumulative share of annual usage value with the corrosion inhibitor, IGB-C515, included', 'unit','percent', 'expected',80.10942671978702, 'tol',5e-07),
    jsonb_build_object('key','igbariam_inhibitor_eoq', 'label','The EOQ of the corrosion inhibitor, unrounded', 'unit','drums', 'expected',86.07898230676612, 'tol',5e-07),
    jsonb_build_object('key','igbariam_inhibitor_relevant_cost', 'label','The relevant cost a year of the corrosion inhibitor at the quantity ordered', 'unit','USD a year', 'expected',4384.044444444444, 'tol',5e-07),
    jsonb_build_object('key','igbariam_inhibitor_rounding_penalty_pct', 'label','The rounding penalty of the corrosion inhibitor order', 'unit','percent', 'expected',0.09922656907414752, 'tol',5e-07),
    jsonb_build_object('key','igbariam_total_write_down', 'label','The total write-down of the four banded items', 'unit','USD', 'expected',24333.449999999997, 'tol',5e-07)
  )
),
(
  'materials', 'intermediate', 'professional',
  'OGIDI, the stock policy of the Ogidi field (synthetic)',
  'Service levels, safety stock and discounts',
  'OGIDI, the stock policy of the Ogidi field (synthetic). One case file comes with this capstone: ogidi_case.json carries five calls under the keys quantityDiscount, safetyStock:cycle-service, safetyStock:fill-rate, safetyStock:periodic and poissonStock; paste it into the stock calculator and choose the block each value needs. Production tubing: a demand of 420 joints a year, an order cost of 2650, a holding rate of 0.22, the incremental schedule 318 from 0; 296.5 from 100; 281.25 from 250, no rounding. The filter element, periods in months, three calls: continuous review at a cycle service level: a demand of 11.5 a month with a standard deviation of 4.2, a lead time of 1.75 months with a standard deviation of 0.35, a review period of 0, the cycle-service measure at 0.975, safety factor rounding none, a minimum safety factor of 0 and no rounding. continuous review at a fill rate: a demand of 11.5 a month with a standard deviation of 4.2, a lead time of 1.75 months with a standard deviation of 0.35, a review period of 0, the fill-rate measure at 0.985, an order quantity of 46, safety factor rounding none, a minimum safety factor of 0 and no rounding. monthly review: a demand of 11.5 a month with a standard deviation of 4.2, a lead time of 1.75 months with a standard deviation of 0, a review period of 1, the cycle-service measure at 0.95, safety factor rounding none, a minimum safety factor of 0 and no rounding. The valve repair kit: a demand of 0.35 a month, Poisson, a lead time of 3.5 months and a review period of 1, the fill-rate measure at 0.97 with an order quantity of 2. No value depends on any of the readings the engine states (twelve significant digits, halves upward, a minimum met at or above it, a tie to the smaller quantity or fewer spares, a Poisson target met at or above it, the cover limit exceeded strictly above it, a stockout at equality, the P90 as the low figure) or on a Monte Carlo draw, and every input a value needs is stated here or in the case file: the engine holds no default for any of them. Report six values: the order quantity of production tubing under the incremental schedule; its total cost a year; the safety stock of the filter element at the cycle service level; the safety factor k for the fill rate, unrounded; the order-up-to level under monthly review, unrounded; and the expected units short a cycle of the valve repair kit at its level. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','ogidi_tubing_discount_quantity', 'label','The order quantity of production tubing under the incremental schedule', 'unit','joints', 'expected',341.9374388995919, 'tol',5e-07),
    jsonb_build_object('key','ogidi_tubing_discount_total_cost', 'label','The total cost a year of production tubing at that quantity', 'unit','USD a year', 'expected',139938.25403191225, 'tol',5e-07),
    jsonb_build_object('key','ogidi_filter_csl_safety_stock', 'label','The safety stock of the filter element at the cycle service level', 'unit','elements', 'expected',13.446927812769554, 'tol',5e-07),
    jsonb_build_object('key','ogidi_filter_fill_rate_k', 'label','The safety factor k of the filter element for the fill rate, unrounded', 'unit','k', 'expected',0.8992388568905528, 'tol',5e-07),
    jsonb_build_object('key','ogidi_filter_periodic_level', 'label','The order-up-to level of the filter element under monthly review, unrounded', 'unit','elements', 'expected',43.081260862871815, 'tol',5e-07),
    jsonb_build_object('key','ogidi_kit_poisson_short', 'label','The expected units short a cycle of the valve repair kit at its level', 'unit','kits', 'expected',0.02944488648478305, 'tol',5e-07)
  )
),
(
  'materials', 'advanced', 'expert',
  'UMUCHU, the spares of the Umuchu compressor station (synthetic)',
  'Spares, lead-time risk and the limits',
  'UMUCHU, the spares of the Umuchu compressor station (synthetic). One case file comes with this capstone: umuchu_case.json carries three calls under the keys insuranceSpares, poissonStock and leadTimeRisk; paste it into the spares calculator and choose the block each value needs. The compressor motor, held as an insurance spare under the engine''s one-for-one model: 3.25 failures a year, a lead time of 120 days, 365 days a year, a unit cost of 142500, a holding rate of 0.18, a downtime cost of 24750 a day, searched from 0 to 8 spares. The seal cartridge: a demand of 0.185 a month, Poisson, a lead time of 5 months and a review period of 2, the fill-rate measure at 0.99 with an order quantity of 3. The same seal''s lead-time risk is in the leadTimeRisk block: a demand a day of a triangle with min 0.004, mode 0.0065 and max 0.011, a lead time in days of a triangle with min 95, mode 140 and max 235, a reorder point of 2, a service level of 0.98, 20000 draws on seed 20291114. Work it and read its P90 as the low figure; it is sampled, and no value below is taken from it. No value depends on any of the readings the engine states (twelve significant digits, halves upward, a minimum met at or above it, a tie to the smaller quantity or fewer spares, a Poisson target met at or above it, the cover limit exceeded strictly above it, a stockout at equality, the P90 as the low figure) or on a Monte Carlo draw, and every input a value needs is stated here or in the case file: the engine holds no default for any of them. Report six values: the total cost a year of the cheapest stock of motor spares; the expected downtime cost a year at that stock; the probability of no shortage at that stock; the fill rate at that stock; the expected units short a cycle of the seal cartridge at its level; and the seal''s achieved fill rate at its level. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','umuchu_motor_total_cost', 'label','The total cost a year of the cheapest stock of motor spares', 'unit','USD a year', 'expected',137085.77395357136, 'tol',5e-07),
    jsonb_build_object('key','umuchu_motor_downtime_cost', 'label','The expected downtime cost a year at that stock', 'unit','USD a year', 'expected',8835.77395357136, 'tol',5e-07),
    jsonb_build_object('key','umuchu_motor_no_shortage', 'label','The probability of no shortage at that stock', 'unit','probability', 'expected',0.9991652298224614, 'tol',5e-07),
    jsonb_build_object('key','umuchu_motor_fill_rate', 'label','The fill rate of the motor spares at that stock', 'unit','probability', 'expected',0.9951783165594128, 'tol',5e-07),
    jsonb_build_object('key','umuchu_seal_poisson_short', 'label','The expected units short a cycle of the seal cartridge at its level', 'unit','seals', 'expected',0.013157720830544672, 'tol',5e-07),
    jsonb_build_object('key','umuchu_seal_poisson_fill_rate', 'label','The achieved fill rate of the seal cartridge at its level', 'unit','probability', 'expected',0.9956140930564851, 'tol',5e-07)
  )
)
on conflict (app_slug, tier) do nothing;
